## Why This Is Asked
This question tests mastery of advanced data structure design by combining segment trees with multisets to handle weighted intervals with duplicate support. It also evaluates understanding of binary search applied to aggregated data structures for kth largest queries.

## Key Concepts
- **Coordinate compression** on endpoints to discretize the domain
- **Segment tree** where each node stores a multiset of weights for intervals covering that node's range
- **Interval decomposition** into O(log n) nodes for efficient updates
- **Path aggregation** for point sum queries
- **Binary search over weight values** with counts from multisets to support kthLargest queries

## Code Example
```javascript
class IntervalDS {
  constructor(coords) {
    this.coords = coords;
    this.N = coords.length;
    this.tree = Array(4 * this.N).fill(null).map(() => new Map());
    this.sums = Array(4 * this.N).fill(0);
  }

  insert(l, r, w) {
    this.update(1, 0, this.N - 1, l, r, w, 1);
  }

  erase(l, r, w) {
    this.update(1, 0, this.N - 1, l, r, w, -1);
  }

  update(node, start, end, l, r, w, delta) {
    if (r < start || end < l) return;
    if (l <= start && end <= r) {
      const count = this.tree[node].get(w) || 0;
      this.tree[node].set(w, count + delta);
      if (this.tree[node].get(w) === 0) this.tree[node].delete(w);
      this.sums[node] += w * delta;
      return;
    }
    const mid = Math.floor((start + end) / 2);
    this.update(node * 2, start, mid, l, r, w, delta);
    this.update(node * 2 + 1, mid + 1, end, l, r, w, delta);
    this.sums[node] = this.sums[node * 2] + this.sums[node * 2 + 1];
  }

  sumAtPoint(x) {
    return this.querySum(1, 0, this.N - 1, x);
  }

  querySum(node, start, end, x) {
    if (x < start || x > end) return 0;
    if (start === end) return this.sums[node];
    const mid = Math.floor((start + end) / 2);
    return this.sums[node] + 
      (x <= mid ? this.querySum(node * 2, start, mid, x) 
                : this.querySum(node * 2 + 1, mid + 1, end, x));
  }

  kthLargest(x, k) {
    const weights = [...new Set(this.getWeightsAtPoint(x))].sort((a, b) => b - a);
    if (k > weights.length) return null;
    return weights[k - 1];
  }

  getWeightsAtPoint(x) {
    const result = [];
    this.collectWeights(1, 0, this.N - 1, x, result);
    return result;
  }

  collectWeights(node, start, end, x, result) {
    if (x < start || x > end) return;
    for (const [w, count] of this.tree[node]) {
      result.push(...Array(count).fill(w));
    }
    if (start === end) return;
    const mid = Math.floor((start + end) / 2);
    this.collectWeights(node * 2, start, mid, x, result);
    this.collectWeights(node * 2 + 1, mid + 1, end, x, result);
  }
}
```

## Why This Is Asked
This question tests understanding of order statistics in dynamic multisets with duplicates and efficient prefix queries—skills fundamental to database indexing and ranking problems.

## Key Concepts
- **Balanced BST with per-node counts and subtree sizes** enables O(log n) operations
- **Handling duplicates via dupCount** avoids unnecessary node creation
- **getRank as a prefix-count query** is analogous to order statistics

## Code Example
```javascript
class Node {
  constructor(key) {
    this.key = key;
    this.dup = 1;
    this.left = null;
    this.right = null;
  }

  get size() {
    return this.dup + (this.left?.size ?? 0) + (this.right?.size ?? 0);
  }
}

class Treap {
  constructor() {
    this.root = null;
  }

  insert(key) {
    this.root = this._insert(this.root, key);
  }

  _insert(node, key) {
    if (!node) return new Node(key);
    if (key === node.key) {
      node.dup++;
    } else if (key < node.key) {
      node.left = this._insert(node.left, key);
    } else {
      node.right = this._insert(node.right, key);
    }
    return node;
  }

  erase(key) {
    this.root = this._erase(this.root, key);
  }

  _erase(node, key) {
    if (!node) return null;
    if (key === node.key) {
      node.dup--;
      if (node.dup === 0) return this._merge(node.left, node.right);
    } else if (key < node.key) {
      node.left = this._erase(node.left, key);
    } else {
      node.right = this._erase(node.right, key);
    }
    return node;
  }

  _merge(left, right) {
    if (!left || !right) return left ?? right;
    // Simplified: in a real Treap, merge by priority
    return this._bstMerge(left, right);
  }

  _bstMerge(left, right) {
    if (!left) return right;
    if (!right) return left;
    const node = left;
    node.right = this._bstMerge(node.right, right);
    return node;
  }

  getRank(v) {
    return this._getRank(this.root, v);
  }

  _getRank(node, v) {
    if (!node) return 0;
    if (v < node.key) {
      return this._getRank(node.left, v);
    }
    const leftSize = node.left?.size ?? 0;
    return leftSize + node.dup + this._getRank(node.right, v);
  }
}
```

